19	  const h = await createHost();
20	  assert.deepEqual(await h.start(), { ok: true });
21	  assert.equal((await h.start()).ok, false);
22	  const msgs = await h.inFlight();
23	  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
24	  await h.deliverAll();
25	  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
26	  assert.deepEqual(await h.workDone('worker0'), { ok: true });
27	  const [r] = await h.inFlight();
28	  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
29	  await h.deliver(r.id);
30	  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
