import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, retried0 = false, retried1 = false) => ({ status, task0, task1, retried0, retried1 });

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal(await h.worker('run'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('nope')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliver(r.id);
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned'));
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed'));
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  const [r] = await h.inFlight();
  await h.deliver(r.id);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', false, true));
  const [a] = await h.inFlight();
  assert.deepEqual([a.from, a.to, a.action, a.data], ['run', 'worker1', 'Assign', {}]);
  await h.deliver(a.id);
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed', false, true));
  assert.deepEqual(await h.inFlight(), []);
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', false, true));
});

test('a retried task can complete', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();
  await h.workDone('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', true, false));
});

test('a failure while cancelling is not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

test('cancel races with a completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0');
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.inFlight()).filter((m) => m.action === 'Abort').length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('timeout fails the task, aborts the worker, and is not retried', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  assert.deepEqual((await h.inFlight()).map((m) => [m.from, m.to, m.action, m.data]), [['run', 'worker0', 'Abort', {}]]);
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.deliverAll();   // the worker's cancelled report is ignored
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed'));
  assert.equal((await h.taskTimeout(1)).ok, false);
});

test('a late report after a timeout is ignored', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker1');          // report in flight
  await h.taskTimeout(1);
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed'));
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'failed'));
  await h.cancel(); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'cancelled', 'failed'));
});

test('timeout while cancelling ends the run', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed'));
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed'));
});

test('cancel after a report only aborts the assigned task', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  await h.cancel();
  assert.deepEqual((await h.inFlight()).map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled'));
  assert.equal((await h.cancel()).ok, false);
});
